package com.bank.blotter.service;

import com.bank.blotter.dto.BlotterResult;
import com.bank.blotter.model.Trade;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import java.math.BigDecimal;
import java.util.*;
import java.util.stream.Collectors;

@Service
@Slf4j
public class BlotterService {

    private final List<Trade> trades = List.of(
        new Trade("TRD-001", "RELIANCE", "BUY",  new BigDecimal("245050"),  "SETTLED"),
        new Trade("TRD-002", "TCS",      "BUY",  new BigDecimal("176000"),  "SETTLED"),
        new Trade("TRD-003", "RELIANCE", "SELL", new BigDecimal("123750"),  "SETTLED"),
        new Trade("TRD-004", "TCS",      "SELL", new BigDecimal("88750"),   "PENDING"),
        new Trade("TRD-005", "HDFC",     "BUY",  new BigDecimal("330150"),  "SETTLED"),
        new Trade("TRD-006", "RELIANCE", "BUY",  new BigDecimal("490100"),  "SETTLED"),
        new Trade("TRD-007", "HDFC",     "SELL", new BigDecimal("165075"),  "PENDING")
    );

    public BlotterResult generateBlotter() {
        Map<String, List<String>> variations = new LinkedHashMap<>();

        // ═══ 1. Symbol ASC, then Amount DESC ═══
        List<String> symbolThenAmount = trades.stream()
            .sorted(Comparator.comparing(Trade::symbol)
                .thenComparing(Trade::amount, Comparator.reverseOrder()))
            .map(this::format)
            .toList();
        variations.put("symbol_ASC_amount_DESC", symbolThenAmount);

        // ═══ 2. Amount DESC only (single field) ═══
        List<String> byAmountDesc = trades.stream()
            .sorted(Comparator.comparing(Trade::amount).reversed())
            .map(this::format)
            .toList();
        variations.put("amount_DESC", byAmountDesc);

        // ═══ 3. Symbol ASC, Side ASC, Amount DESC ═══
        List<String> triple = trades.stream()
            .sorted(Comparator.comparing(Trade::symbol)
                .thenComparing(Trade::side)
                .thenComparing(Trade::amount, Comparator.reverseOrder()))
            .map(this::format)
            .toList();
        variations.put("symbol_ASC_side_ASC_amount_DESC", triple);

        // ═══ 4. Status ASC (PENDING first), then Amount DESC ═══
        List<String> statusThenAmount = trades.stream()
            .sorted(Comparator.comparing(Trade::status)
                .thenComparing(Trade::amount, Comparator.reverseOrder()))
            .map(this::format)
            .toList();
        variations.put("status_ASC_amount_DESC", statusThenAmount);

        return new BlotterResult(variations);
    }

    private String format(Trade t) {
        return t.tradeId() + " " + t.symbol() + " " + t.side() + " Rs." + t.amount();
    }
}
