package com.bank.blotter.service;

import org.junit.jupiter.api.Test;
import java.util.*;
import java.util.stream.Collectors;
import static org.assertj.core.api.Assertions.*;

class MultiFieldSortTest {

    record Emp(String name, int age, int salary) {}

    @Test
    void sortByNameThenAge() {
        List<Emp> emps = List.of(new Emp("Priya", 28, 100), new Emp("Amit", 30, 200),
            new Emp("Priya", 35, 150), new Emp("Amit", 25, 180));

        List<Emp> sorted = emps.stream()
            .sorted(Comparator.comparing(Emp::name).thenComparingInt(Emp::age))
            .toList();

        assertThat(sorted.get(0).name()).isEqualTo("Amit");
        assertThat(sorted.get(0).age()).isEqualTo(25);  // Amit 25 before Amit 30
        assertThat(sorted.get(2).name()).isEqualTo("Priya");
        assertThat(sorted.get(2).age()).isEqualTo(28);  // Priya 28 before Priya 35
    }

    @Test
    void sortBySalaryDescThenNameAsc() {
        List<Emp> emps = List.of(new Emp("Priya", 28, 200), new Emp("Amit", 30, 200),
            new Emp("Rajesh", 35, 300));

        List<Emp> sorted = emps.stream()
            .sorted(Comparator.comparingInt(Emp::salary).reversed()
                .thenComparing(Emp::name))
            .toList();

        assertThat(sorted.get(0).name()).isEqualTo("Rajesh");  // highest salary
        assertThat(sorted.get(1).name()).isEqualTo("Amit");     // tied salary, A before P
        assertThat(sorted.get(2).name()).isEqualTo("Priya");
    }

    @Test
    void thenComparingOnlyTriggersOnEqualPrimary() {
        List<Emp> emps = List.of(new Emp("A", 30, 100), new Emp("B", 25, 200),
            new Emp("A", 28, 150));

        List<Emp> sorted = emps.stream()
            .sorted(Comparator.comparing(Emp::name).thenComparingInt(Emp::age))
            .toList();

        // A(28) before A(30) — thenComparing age triggered for equal names
        assertThat(sorted.get(0)).isEqualTo(new Emp("A", 28, 150));
        assertThat(sorted.get(1)).isEqualTo(new Emp("A", 30, 100));
        // B(25) — no thenComparing needed (unique name)
        assertThat(sorted.get(2)).isEqualTo(new Emp("B", 25, 200));
    }

    @Test
    void nullSafeSorting() {
        List<String> data = Arrays.asList("C", null, "A", null, "B");
        List<String> sorted = data.stream()
            .sorted(Comparator.nullsLast(Comparator.naturalOrder()))
            .toList();
        assertThat(sorted).containsExactly("A", "B", "C", null, null);
    }
}
